  },
  "components": {
    "schemas": {
      "BukuInput": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "judul",
          "tersedia"
        ],
        "properties": {
          "judul": {
            "type": "string",
            "description": "Setelah trim, panjang 1-120 unit UTF-16."
          },
          "tersedia": {
            "type": "boolean",
            "description": "Status ketersediaan buku di katalog (true atau false)."
          }
        }
      },
      "Buku": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "id",
          "judul",
          "tersedia"
        ],
        "properties": {
          "id": {
            "type": "integer",
            "minimum": 1,
            "maximum": 9007199254740991,
            "description": "ID buku integer positif hasil generate server."
          },
          "judul": {
            "type": "string",
            "description": "Setelah trim, panjang 1-120 unit UTF-16."
          },
          "tersedia": {
            "type": "boolean",
            "description": "Status ketersediaan buku di katalog (true atau false)."
          }
        }
      },
      "BukuResponse": {
        "type": "object",
        "required": [
          "success",
          "data"
        ],
        "properties": {
          "success": {
            "const": true,
            "description": "Menandakan operasi berhasil."
          },
          "data": {
            "$ref": "#/components/schemas/Buku"
          }
        }
      },
      "DaftarResponse": {
        "type": "object",
        "required": [
          "success",
          "data"
        ],
        "properties": {
          "success": {
            "const": true,
            "description": "Menandakan operasi berhasil."
          },
          "data": {
            "type": "array",
            "items": {
              "$ref": "#/components/schemas/Buku"
            }
          }
        }
      },
      "ErrorResponse": {
        "type": "object",
        "required": [
          "success",
          "error"
        ],
        "properties": {
          "success": {
            "const": false,
            "description": "Menandakan operasi gagal."
          },
          "error": {
            "type": "object",
            "required": [
              "code",
              "message"
            ],
            "properties": {
              "code": {
                "type": "string",
                "description": "Kode kesalahan standar aplikasi."
              },
              "message": {
                "type": "string",
                "description": "Pesan kesalahan ramah pengguna."
              }
            }
          }
        }
